/* language helpers */
function detectLang(){
  const ls=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||"en"]).map(x=>String(x));
  for(const l of ls){const s=l.toLowerCase();
    if(s==="pt-br")return "pt-BR";if(s.startsWith("pt"))return "pt-PT";if(s.startsWith("es"))return "es";if(s.startsWith("fr"))return "fr";if(s.startsWith("zh"))return "zh";if(s.startsWith("en"))return "en"}
  return "en";
}
function detectRegion(){
  const tz=(()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||""}catch(e){return ""}})();
  const byTz={"Europe/Lisbon":"PT","Atlantic/Madeira":"PT","Atlantic/Azores":"PT","Europe/Madrid":"ES","Atlantic/Canary":"ES","Africa/Ceuta":"ES","Europe/Paris":"FR","Europe/London":"GB","Asia/Shanghai":"CN","Asia/Urumqi":"CN"};
  if(byTz[tz])return byTz[tz];
  if(tz.startsWith("America/")&&/Sao_Paulo|Bahia|Fortaleza|Recife|Belem|Manaus|Cuiaba|Campo_Grande|Porto_Velho|Boa_Vista|Rio_Branco|Maceio|Araguaina|Santarem|Noronha|Eirunepe/.test(tz))return "BR";
  for(const l of (navigator.languages||[navigator.language||""])){const m=String(l).match(/[-_]([A-Za-z]{2})$/);if(m&&COUNTRIES[m[1].toUpperCase()])return m[1].toUpperCase()}
  return "";
}
let LANG="en";
