function t(k,v){let s=(STR[LANG]&&STR[LANG][k]!==undefined)?STR[LANG][k]:STR.en[k];if(s===undefined)return k;
  if(typeof s==="object"&&!Array.isArray(s)&&("other" in s)){let form="other";try{form=new Intl.PluralRules(loc()).select(v&&v.n!==undefined?v.n:0)}catch(e){}s=s[form]||s.other}
  if(typeof s!=="string")return s;return v?s.replace(/\{(\w+)\}/g,(m,x)=>v[x]!==undefined?v[x]:m):s}
